const SHALLABUG_INFO={id:"shallabug-wetland",name:"Shallabug Wetland Conservation Reserve",location:"Ganderbal & Srinagar Districts, Jammu & Kashmir, India",state:"Jammu & Kashmir",coordinates:{lat:34.167,lng:74.717},area:"16.75 km² (1,675 hectares)",ramsarYear:2022,ramsarSiteNo:2490,wetlandType:"Extensive Marshland & Willow Reserve",climate:"Sub-Mediterranean Temperate",bestTime:"November to March",nearestTransport:{town:"Ganderbal (8 km) / Srinagar (15 km)",airport:"Srinagar International Airport (25 km)",railway:"Srinagar Railway Station (20 km)"},quickStats:[{label:"Ramsar Designated",value:"2022",icon:"💧"},{label:"Reserve Area",value:"16.75 km²",icon:"🌾"},{label:"Wintering Waterfowl",value:"200,000+",icon:"🪿"},{label:"Reed Bed Habitat",value:"Extensive Marsh",icon:"🌿"},{label:"Willow Plantations",value:"Eco-Livelihood",icon:"🪵"},{label:"Community Heritage",value:"Wicker Craft",icon:"🧺"}]},ECOLOGY_HYDROLOGY={overview:"Shallabug Wetland Conservation Reserve is a vast natural marshland located in the floodplains of the Sind and Jhelum rivers near Srinagar. It comprises open water expanses, extensive reed beds, and submerged lotus and water lily vegetation.",marshEcology:"The reserve forms a vital habitat along the Central Asian Flyway. Its thick beds of Typha angustifolia and Phragmites communis offer undisturbed nesting and feeding sanctuaries for migratory wildfowl.",communityLivelihood:"Local Kashmiri villagers depend on Shallabug for sustainable harvesting of wicker willow (used in famous Kashmiri wicker craft), reed mat weaving, and traditional seasonal fishing.",conservationStatus:"Designated as a Ramsar Site of International Importance in 2022. Protection efforts focus on preventing siltation, regulating water sluices, and preserving bird roosting grounds."},BIRD_SPECIES=[{id:"eurasian-wigeon",name:"Eurasian Wigeon",scientificName:"Mareca penelope",category:"migratory-waterfowl",status:"Least Concern",season:"October to March",diet:"Aquatic vegetation, marsh grasses",wingspan:"75–86 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Eurasian_Wigeon_male.jpg/800px-Eurasian_Wigeon_male.jpg",description:"Dabbling duck with rich chestnut head and buff yellow forehead stripe on males. Grazes on aquatic vegetation in open water channels."},{id:"garganey",name:"Garganey",scientificName:"Spatula querquedula",category:"migratory-waterfowl",status:"Least Concern",season:"Spring & Autumn Transit",diet:"Small mollusks, aquatic larvae, seeds",wingspan:"58–69 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Garganey_male.jpg/800px-Garganey_male.jpg",description:"Distinctive small dabbling duck with broad white crescent stripe over the eye in breeding males."},{id:"greylag-goose",name:"Greylag Goose",scientificName:"Anser anser",category:"migratory-waterfowl",status:"Least Concern",season:"November to February",diet:"Wetland shoots, roots, grains",wingspan:"147–180 cm",icon:"🪿",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Greylag_Goose_Anser_anser.jpg/800px-Greylag_Goose_Anser_anser.jpg",description:"Large grey goose that winters in thousands across Shallabug's open marshy flats."},{id:"ferruginous-pochard",name:"Ferruginous Pochard",scientificName:"Aythya nyroca",category:"migratory-waterfowl",status:"Near Threatened",season:"November to March",diet:"Aquatic plant roots, aquatic insects",wingspan:"63–67 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Ferruginous_duck_%28Aythya_nyroca%29_male.jpg/800px-Ferruginous_duck_%28Aythya_nyroca%29_male.jpg",description:"Diving duck species with deep mahogany plumage that nests within Shallabug's thick dense reed beds."}],MAP_HOTSPOTS=[{id:"shallabug-watchtower",title:"Shallabug Eco Watchtower",lat:34.169,lng:74.719,type:"Observation",description:"Wooden watchtower providing panoramic birdwatching views across open water channels and willow stands."},{id:"willow-marsh-trail",title:"Willow Marsh Channel",lat:34.164,lng:74.714,type:"Boat Trail",description:"Traditional shikara navigation route used for wildlife monitoring and eco-tourism."}],GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Eurasian_Wigeon_male.jpg/800px-Eurasian_Wigeon_male.jpg",caption:"Eurasian Wigeon in Shallabug marshland",category:"Fauna"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Garganey_male.jpg/800px-Garganey_male.jpg",caption:"Garganey swimming among lotus leaves",category:"Fauna"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Greylag_Goose_Anser_anser.jpg/800px-Greylag_Goose_Anser_anser.jpg",caption:"Greylag Geese roosting at sunset",category:"Fauna"}];"undefined"!=typeof module&&module.exports&&(module.exports={SHALLABUG_INFO:SHALLABUG_INFO,ECOLOGY_HYDROLOGY:ECOLOGY_HYDROLOGY,BIRD_SPECIES:BIRD_SPECIES,MAP_HOTSPOTS:MAP_HOTSPOTS,GALLERY_IMAGES:GALLERY_IMAGES});